CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE carriers(id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE memberships(carrier_id text REFERENCES carriers(id), uid text, role text NOT NULL CHECK(role IN ('dispatcher','driver','simulator','worker')), driver_id text, PRIMARY KEY(carrier_id,uid));
CREATE TABLE scenarios(carrier_id text REFERENCES carriers(id), id text, clock timestamptz NOT NULL, initial_state jsonb NOT NULL, seed integer NOT NULL, version integer NOT NULL DEFAULT 1, PRIMARY KEY(carrier_id,id));
CREATE TABLE source_imports(carrier_id text REFERENCES carriers(id), id uuid, sha256 text NOT NULL, filename text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(carrier_id,id), UNIQUE(carrier_id,sha256));
CREATE TABLE source_rows(carrier_id text, import_id uuid, sheet text, row_number integer, raw jsonb NOT NULL, normalized jsonb, issues jsonb NOT NULL DEFAULT '[]', duplicate_of integer, PRIMARY KEY(carrier_id,import_id,sheet,row_number), FOREIGN KEY(carrier_id,import_id) REFERENCES source_imports(carrier_id,id));
CREATE TABLE resources(carrier_id text REFERENCES carriers(id), id text, kind text NOT NULL CHECK(kind IN ('driver','truck','trailer','dock')), version integer NOT NULL DEFAULT 1, body jsonb NOT NULL, PRIMARY KEY(carrier_id,id));
CREATE TABLE loads(carrier_id text REFERENCES carriers(id), id text, version integer NOT NULL, status text NOT NULL CHECK(status IN ('open','offered','accepted','in_transit','completed')), body jsonb NOT NULL, PRIMARY KEY(carrier_id,id));
CREATE TABLE stops(carrier_id text, load_id text, id text, sequence integer NOT NULL, location geography(Point,4326) NOT NULL, radius_m double precision NOT NULL CHECK(radius_m>0), body jsonb NOT NULL, PRIMARY KEY(carrier_id,load_id,id), FOREIGN KEY(carrier_id,load_id) REFERENCES loads(carrier_id,id));
CREATE TABLE assignments(carrier_id text, id uuid, load_id text, driver_id text, truck_id text, trailer_id text, start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, version integer NOT NULL, status text NOT NULL CHECK(status IN ('offered','accepted','rejected','completed','superseded')), PRIMARY KEY(carrier_id,id), FOREIGN KEY(carrier_id,load_id) REFERENCES loads(carrier_id,id), FOREIGN KEY(carrier_id,driver_id) REFERENCES resources(carrier_id,id), FOREIGN KEY(carrier_id,truck_id) REFERENCES resources(carrier_id,id), FOREIGN KEY(carrier_id,trailer_id) REFERENCES resources(carrier_id,id), CHECK(end_at>start_at));
CREATE UNIQUE INDEX one_active_assignment ON assignments(carrier_id,load_id) WHERE status IN ('offered','accepted');
CREATE TABLE reservations(carrier_id text, id uuid, assignment_id uuid, resource_id text, period tstzrange NOT NULL, active boolean NOT NULL DEFAULT true, PRIMARY KEY(carrier_id,id), FOREIGN KEY(carrier_id,assignment_id) REFERENCES assignments(carrier_id,id), FOREIGN KEY(carrier_id,resource_id) REFERENCES resources(carrier_id,id), CHECK(NOT isempty(period) AND NOT lower_inf(period) AND NOT upper_inf(period)), EXCLUDE USING gist(carrier_id WITH =,resource_id WITH =,period WITH &&) WHERE(active));
CREATE TABLE maintenance_holds(carrier_id text, id uuid, resource_id text, period tstzrange NOT NULL, reason text NOT NULL, PRIMARY KEY(carrier_id,id), FOREIGN KEY(carrier_id,resource_id) REFERENCES resources(carrier_id,id));
CREATE TABLE commands(carrier_id text REFERENCES carriers(id), uid text, key text, fingerprint text NOT NULL, result jsonb, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(carrier_id,uid,key));
CREATE TABLE events(carrier_id text REFERENCES carriers(id), cursor bigint GENERATED ALWAYS AS IDENTITY, kind text NOT NULL, actor text NOT NULL, body jsonb NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(carrier_id,cursor));
CREATE INDEX events_cursor ON events(carrier_id,cursor);
CREATE TABLE proposals(carrier_id text, id uuid, load_id text, expected_version integer NOT NULL, revision integer NOT NULL DEFAULT 1, status text NOT NULL CHECK(status IN ('pending','approved','rejected')), body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(carrier_id,id), FOREIGN KEY(carrier_id,load_id) REFERENCES loads(carrier_id,id));
CREATE TABLE approvals(carrier_id text, id uuid, proposal_id uuid, uid text NOT NULL, evidence jsonb NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(carrier_id,id), FOREIGN KEY(carrier_id,proposal_id) REFERENCES proposals(carrier_id,id));
CREATE TABLE work_sessions(carrier_id text, id uuid, driver_id text, started_at timestamptz NOT NULL, ended_at timestamptz, version integer NOT NULL DEFAULT 1, PRIMARY KEY(carrier_id,id), FOREIGN KEY(carrier_id,driver_id) REFERENCES resources(carrier_id,id));
CREATE UNIQUE INDEX one_work_session ON work_sessions(carrier_id,driver_id) WHERE ended_at IS NULL;
CREATE TABLE telemetry(carrier_id text, id text, assignment_id uuid, session_id uuid, at timestamptz NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), location geography(Point,4326) NOT NULL, accuracy_m double precision NOT NULL CHECK(accuracy_m>=0), body jsonb NOT NULL, disposition text NOT NULL, PRIMARY KEY(carrier_id,id), FOREIGN KEY(carrier_id,assignment_id) REFERENCES assignments(carrier_id,id), FOREIGN KEY(carrier_id,session_id) REFERENCES work_sessions(carrier_id,id));
CREATE INDEX telemetry_latest ON telemetry(carrier_id,assignment_id,at DESC) WHERE disposition='applied';
CREATE TABLE stop_visits(carrier_id text, id uuid, assignment_id uuid, load_id text, stop_id text, arrival timestamptz NOT NULL, departure timestamptz, arrival_event text NOT NULL, departure_event text, precision text NOT NULL DEFAULT 'observed_samples', PRIMARY KEY(carrier_id,id), FOREIGN KEY(carrier_id,assignment_id) REFERENCES assignments(carrier_id,id), FOREIGN KEY(carrier_id,load_id,stop_id) REFERENCES stops(carrier_id,load_id,id), FOREIGN KEY(carrier_id,arrival_event) REFERENCES telemetry(carrier_id,id), FOREIGN KEY(carrier_id,departure_event) REFERENCES telemetry(carrier_id,id), CHECK(departure IS NULL OR departure>=arrival));
CREATE UNIQUE INDEX one_open_visit ON stop_visits(carrier_id,assignment_id,stop_id) WHERE departure IS NULL;
CREATE TABLE duty_events(carrier_id text, id uuid, driver_id text, at timestamptz NOT NULL, duty text NOT NULL CHECK(duty IN ('off_duty','on_duty','driving','sleeper')), note text, PRIMARY KEY(carrier_id,id), FOREIGN KEY(carrier_id,driver_id) REFERENCES resources(carrier_id,id));
CREATE TABLE documents(carrier_id text, id uuid, load_id text, object_name text NOT NULL, sha256 text, media_type text NOT NULL, status text NOT NULL, extraction jsonb, version integer NOT NULL DEFAULT 1, PRIMARY KEY(carrier_id,id), FOREIGN KEY(carrier_id,load_id) REFERENCES loads(carrier_id,id));
CREATE TABLE contracts(carrier_id text REFERENCES carriers(id), id text, version integer NOT NULL, free_minutes integer NOT NULL CHECK(free_minutes>=0), rate_cents_per_hour integer NOT NULL CHECK(rate_cents_per_hour>=0), currency text NOT NULL, provenance text NOT NULL, PRIMARY KEY(carrier_id,id));
CREATE TABLE invoice_revisions(carrier_id text, id uuid, visit_id uuid, revision integer NOT NULL, contract_id text, contract_version integer, status text NOT NULL CHECK(status IN ('draft','approved')), body jsonb NOT NULL, approved_by text, PRIMARY KEY(carrier_id,id), UNIQUE(carrier_id,visit_id,revision), FOREIGN KEY(carrier_id,visit_id) REFERENCES stop_visits(carrier_id,id), FOREIGN KEY(carrier_id,contract_id) REFERENCES contracts(carrier_id,id));
CREATE TABLE jobs(carrier_id text REFERENCES carriers(id), id uuid, kind text NOT NULL, status text NOT NULL CHECK(status IN ('pending','running','succeeded','failed')), payload jsonb NOT NULL, result jsonb, attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, PRIMARY KEY(carrier_id,id));
CREATE TABLE outbox(carrier_id text, id uuid, kind text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, attempts integer NOT NULL DEFAULT 0, PRIMARY KEY(carrier_id,id));
